/**
 * Store api key
 * @param {object} req - request object containing api key
 * @param {object} res - response object containing response
 */
async function fetchApiKey(modelId) {
    let _fn = `fetchApiKey`
    try {
        if (modelId == 0) {
            return
        } else {
            let match_gpt_info = `match $gpt_info isa gpt_info, has nrid \"${modelId}\"; get $gpt_info;`
            let opts = {
                "db": "causeway-repo",
                "query": match_gpt_info,
                "query_type": "match",
                "session_type": "DATA",
                "transaction_type": "READ"
            }
            let query_result = await typedbApi.executeQuery(opts)
            console.log(`${_module} [ getPromptInfo ] query_result`, query_result, typeof query_result, query_result.length)
            let llminfo = ["", ""]
            let keys = new Set(_previus_llm_ctx_keys)
            if (query_result.length !== 0) {
                let transaction = await typedbApi.create_transaction(opts.transaction_type)
                let _gpt_info = query_result[0].get("gpt_info").asRemote(transaction)
                let _gpt_info_attributes = await _gpt_info.getHas().collect()
                for await (let attribute of _gpt_info_attributes) {
                    let _label = attribute.type.label.name
                    let attr_value = attribute.value
                    if (keys.has(_label)) {
                        if (_label === "gpt_api_key") { llminfo[0] = attr_value }
                    }
                }
                await typedbApi.close_transaction(opts.transaction_type, transaction)
            }
            console.log(`${_fn} llminfo return `, llminfo)
            return llminfo
        }
    } catch (exception) {
        // console.log(`${_module} exception `, exception)
        throw exception
    }
}
/**
 * Load prompt for causal diagrams
 * @param {object} req - request object contains activeWorkspace, nodes, etc
 * @param {object} res - response object contains formulated prompt
 */
async function loadPrompt(req, res) {
    let _fn = `loadPrompt`
    try {
        let prompt = ""
        if (req.body.activeWorkspace == 0) {
            res.status(200).send({ prompt: prompt })
            return
        } else {
            let nodes = req.body.nodes
            let researchQuestion = req.body.researchQuestion
            let prompt = ""
            let workspace = await getWorkspaceContext(req)
            console.log(`${_module} ${_fn} workspace attributes`, Object.keys(workspace))

            let causal_graph = await createGPTNodeStructure(nodes)
            console.log(`${_module} ${_fn} causal graph`, causal_graph)

            workspace["gpt_research_question"] = workspace["gpt_research_question"] === undefined ? "" : workspace["gpt_research_question"]
            workspace["gpt_research_question"] = workspace["gpt_research_question"] !== researchQuestion ? researchQuestion : workspace["gpt_research_question"]
            prompt = await createPrompt(GPTNodesStructure = causal_graph, researchQuestion = workspace["gpt_research_question"], effect = req.body.outcome, factor = req.body.treatment, factors_list = nodes)
            console.log(`${_module} ${_fn} prompt`, prompt)

            workspace["gpt_prompt"] = prompt
            let updatedFlow = await updateWorkspaceContext(req.body.activeWorkspace, workspace)
            console.log(`${_module} ${_fn} updated flow`, Object.keys(updatedFlow))

            res.status(200).send({ prompt: prompt, updatedFlow: updatedFlow })
            return
        }
    } catch (exception) {
        console.log(`${_module} exception `, exception)
        res.status(500).send({ error: exception })
    }
}

