/**
 * 
 * @param {*} req 
 * @returns 
 */
async function getRecentResult(workspace, req) {
    try {
        // console.log(`${_module} [ getRecentResult ]`, workspace)
        let gpt_recent = workspace.hasOwnProperty("gpt_recent_results") ? workspace["gpt_recent_results"] : []
        gpt_recent.forEach(async (cr_set) => {
            await cr_set.forEach(async (cr) => {
                let nodePairs = [...cr.label.split(/-+>?/g)]
                let cause = await nodePairs[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").trim().replaceAll(";", "")
                let effect = await nodePairs[1].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").trim().replaceAll(";", "")
                await updateSublabel(cause, effect, req.query.nn, cr)
            })
        })
        return gpt_recent
    }
    catch (exception) {
        console.log(`${_module} [ getRecentResult ]exception `, exception)
        return exception
    }
}

async function updateSublabel(cause, effect, nn, cr) {
    try {
        if (nn !== undefined) {
            let causeId = nn.hasOwnProperty(cause) ? nn[cause] : undefined
            let effectId = nn.hasOwnProperty(effect) ? nn[effect] : undefined
            // console.log(`${_module} [ updateSublabel ]cause ${cause} ${cause.length}, causeId ${causeId}, effect ${effect}, effectId ${effectId}\'`)
            if (causeId !== undefined) {
                let causeNode = runtime._.nodes.getNode(causeId)
                let actuallyAdded = false
                if (causeNode !== undefined && causeNode !== null) {
                    if (causeNode.wires !== undefined) {
                        causeNode.wires[0].forEach(wire => {
                            if (wire === effectId) { actuallyAdded = true }
                        })
                    }
                    cr.sublabel = actuallyAdded ? "added" : ""
                }
            } else {
                cr.sublabel = ""
                cr.label = cause + "->" + effect
            }
        } else {
            cr.sublabel = ""
            cr.label = cause + "->" + effect
        }
    } catch (exception) {
        console.log(`${_module} [ updateSublabel ] `, exception)
        throw exception
    }
}

/**
 * Get prompt info 
 * @param {*} req 
 * @param {*} res 
 * @returns 
 */
async function getPromptInfo(req, res) {
    try {
        // console.log(`${_module} [ getPromptInfo ] req `, req.query)
        // match typedb first 
        let match_gpt_info = `match $gpt_info isa gpt_info, has nrid \"${req.query.activeWorkspace}\"; get $gpt_info;`
        let opts = {
            "db": "causeway-repo",
            "query": match_gpt_info,
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ",
            "caller": "get-prompt-info"

        }
        let query_result = await typedbApi.executeQuery(opts)
        // console.log(`${_module} [ getPromptInfo ] query_result`, query_result.length)
        let workspace = {}
        let researchQuestion = ""
        let prompt = ""
        let gpt_info = ["", ""]
        let recent_result = ""
        let keys = new Set(_previus_llm_ctx_keys)
        if (query_result.length !== 0) {
            let transaction = await typedbApi.create_transaction(opts.transaction_type)
            let _gpt_info = query_result[0].get("gpt_info").asRemote(transaction)
            let _gpt_info_attributes = await _gpt_info.getHas().collect()
            for await (let attribute of _gpt_info_attributes) {
                let _label = attribute.type.label.name
                let attr_value = attribute.value
                if (keys.has(_label)) {
                    if (_label === "gpt_research_question") { researchQuestion = attr_value }
                    if (_label === "gpt_prompt") { prompt = attr_value }
                    if (_label === "gpt_recent_results") {
                        attr_value = attr_value.replaceAll(/\'/g, "\"")
                        recent_result = await JSON.parse(attr_value)
                        // console.log("recent results ", recent_result)
                        if (recent_result.length > 0) {
                            for await (let result of recent_result[0]) {
                                let node_pair = result.label.split(/-+>?/g)
                                let cause = node_pair[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                                let effect = node_pair[1].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                                result.checkbox = true
                                result.selected = false
                                result.collapsible = true
                                await updateSublabel(cause, effect, req.query.nn, result)
                            }
                        }
                    }
                    if (_label === "gpt_api_key") { gpt_info[0] = attr_value }
                    if (_label === "gpt_api_org") { gpt_info[0] = attr_value }
                }
            }
            await typedbApi.close_transaction(opts.transaction_type, transaction)
        } else {
            // console.log(`${_module} [ gpt_info ] gpt_info does not exist`)
            workspace = await getWorkspaceContext(req)
            researchQuestion = await getResearchQuestion(workspace)
            prompt = await getPrompt(workspace)
            gpt_info = await getGPTInfo(workspace)
            recent_result = await getRecentResult(workspace, req)
        }
        // needed to undo extra \" when stored in typedb
        researchQuestion = researchQuestion.replaceAll('\\', '')
        // console.log(`${_module} [ gpt_info ] retrieve gpt info`, gpt_info)
        res.status(200).send({ researchQuestion: researchQuestion, prompt: prompt, gptInfo: gpt_info, gpt_recent_results: recent_result })
    } catch (exception) {
        console.log(`${_module} getPromptInfo exception `, exception)
        res.status(500).send({ error: exception })
    }
}

/** 
 * process response from ChatGPT
 */
async function processGPTAnswer(answer) {
    try {
        var nodePairSet = await answer.map(response => {
            let digraph = response.replaceAll("+", "").replaceAll("\'", "")
            // split digraph into sub array
            let substrings = digraph.split("\n")
            let nodes = {}
            let relations = new Set()
            if (substrings !== undefined) {
                substrings.forEach(string => {
                    // identify statement type
                    // node statement
                    if (string.includes("label")) {
                        console.log("Node statement: ", string)
                        let _node = string.split("[")
                        let node_id = _node[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        console.log("Node id: ", node_id)
                        // only look at statements as opposed to sentences containing the word label
                        if (_node[1] !== undefined) {
                            let label = _node[1]
                                .match(/(?:"[^"]*"|^[^"]*$)/)[0]
                            nodes[node_id] = label
                        }
                        console.log(nodes)
                    }
                    // edge 
                    let edge_string = string.match(/-+>?/g) ? string.match(/-+>?/g) : []
                    if (edge_string.length > 0) {
                        let node_pair = string.split(/-+>?/g)
                        let cause = node_pair[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        let effect = node_pair[1].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        if (effect.includes("label")) {
                            effect = effect.split("[")[0].replaceAll(" ", "")
                        }

                        // take out everything in <effect>
                        let causeName = nodes[cause] ? nodes[cause] : cause
                        let effectName = nodes[effect] ? nodes[effect] : effect

                        // 
                        console.log("\tcause: ", cause.match(/(?<=<cause>)(.*?)(?=<cause>)/g))
                        if (cause.match(/(?<=<cause>)(.*?)(?=<cause>)/g) !== null) {
                            if (cause.match(/(?<=<cause>)(.*?)(?=<cause>)/g).length > 0) {
                                let _tempcause = cause.match(/(?<=<cause>)(.*?)(?=<cause>)/g)[0]
                                causeName = nodes[_tempcause] ? nodes[_tempcause] : _tempcause
                            }
                        }

                        console.log("\teffect: ", effect.match(/(?<=<effect>)(.*?)(?=<effect>)/g))
                        if (effect.match(/(?<=<effect>)(.*?)(?=<effect>)/g) !== null) {
                            if (effect.match(/(?<=<effect>)(.*?)(?=<effect>)/g).length > 0) {
                                let _tempeffect = effect.match(/(?<=<effect>)(.*?)(?=<effect>)/g)[0]
                                effectName = nodes[_tempeffect] ? nodes[_tempeffect] : _tempeffect
                            }
                        }
                        console.log("\tcause in relation : ", causeName, causeName.length)
                        console.log("\teffect in relation ", effectName, effectName.length)
                        causeName = causeName.replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        effectName = effectName.replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        if (causeName.length > 0 && effectName.length > 0) {
                            relations.add(causeName + "->" + effectName)
                        }
                    }
                })
            }
            let nodePairs = Array.from(relations).map(relation => {
                // prepare item to be added to list as disction
                let node = {
                    "label": relation,
                    "checkbox": true, // (optional) if present, display checkbox accordingly
                    "selected": false, // (optional) whether the item is selected or not
                    "collapsible": true, // prevent a parent item from being collapsed. default true.
                    "sublabel": ""
                }
                return node
            })
            return nodePairs
        })
        // console.log(`${_module} processGPTAnswer nodePairSets `, nodePairSet)
        return nodePairSet
    } catch (exception) {
        console.log(`${_module} processGPTAnswer exception `, exception)
        throw exception
    }
}


