async function updateDownstream(wires, flow, nodesToAdd, effectNode, linksToAdd) {
    console.log(`${_module} updateDownStream wires. effectNode. `, wires, effectNode)
    for await (let _effectNodeId of wires) {
        for await (let node of nodesToAdd) {
            if (node.id === _effectNodeId) {
                console.log(`${_module} updateDownStream  node and effect node x ${node.x} , ${effectNode.x}`)
                if ((node.x - 275) < effectNode.x) {
                    console.log(`${_module} node.id ${node.id} node.x ${node.x}`)
                    node.x += 275
                }
                if (linksToAdd.hasOwnProperty(node.id)) {
                    await updateDownstream(linksToAdd[node.id], flow, nodesToAdd, node, linksToAdd)
                }
            }
        }
    }
    return
}

async function addNewRelations(req, res) {
    let _func_name = "[addNewRelations ]"
    try {
        let workspace = await getWorkspaceContext(req)
        let gpt_recent = workspace["gpt_recent_results"] ? workspace["gpt_recent_results"] : []
        let flow = await runtime._.nodes.getFlow(req.body.activeWorkspace)
        let flowId = flow !== null ? flow.id : req.body.activeWorkspace
        console.log(`${_module} ${_func_name} : flowId ${flowId} `)
        let nn_exists = Object.keys(req.body).includes("nn")
        let nodesToAdd = []
        linksToAdd = {}
        let seenNodes = {}
        for await (let relation of req.body.newRelations) {
            console.log(`======================= ${_func_name} ===================================`)
            relation = relation.split(/-+>?/g)
            console.log(`${_module} ${_func_name} relation ${relation}`)
            let causeName = relation[0]
            let effectName = relation[1]
            let causeExists = false
            let effectExists = false
            let causeNode = {}
            let effectNode = {}
            let causeNodeId = ""
            let effectNodeId = ""
            let incrementY = 75
            let multiple = 0

            if (nn_exists) {
                causeExists = req.body.nn[causeName] ? true : false
                causeNode = req.body.nn[causeName] ? req.body.nn[causeName] : causeNode
                effectExists = req.body.nn[effectName] ? true : false
                effectNode = req.body.nn[effectName] ? req.body.nn[effectName] : effectNode
            }
            console.log(`${_module} ${_func_name} nodesToAdd.length ${nodesToAdd.length}`)
            let nodeX = 200
            let nodeY = 150

            // need to check if node has been added on this run as it hasn't been stored to flow yet
            for await (let node of nodesToAdd) {
                if (causeName === node.name) {
                    console.log("node previously added in this run")
                    causeNode = node
                    causeExists = true
                    nodeX = node.x
                    nodeY = node.y
                }
                if (effectName === node.name) {
                    console.log("effect node previously added in this run")
                    effectNode = node
                    effectExists = true
                    nodeX = node.x
                    nodeY = node.y
                }
            }
            if (causeExists && effectExists) {
                /**  do nothing */
                console.log(`${_module} addNewRelations [ both nodes exist]`)
                console.log(`${_module} addNewRelations causeNode ${causeNode} effectNode ${effectNode}`)

                let effectQueryValue = req.body.nn !== undefined ? req.body.nn[effectName] : effectNode.id
                let causeQueryValue = req.body.nn !== undefined ? req.body.nn[causeName] : causeNode.id

                //1 find effect node and store its x and y values
                if (flow !== null) {
                    for await (let node of flow.nodes) {
                        if (node.id === effectQueryValue) { effectNode = node }
                        if (node.id === causeQueryValue) { causeNode = node }
                    }
                }

                // find effect and cause node in flow
                if (linksToAdd.hasOwnProperty(causeNode.id)) {
                    let items = new Set(linksToAdd[causeNode.id])
                    if (!items.has(effectNode.id)) {
                        linksToAdd[causeNode.id].push(effectNode.id)
                    }
                } else {
                    linksToAdd[causeNode.id] = [effectNode.id]
                }
                console.log(`${_module} addNewRelations linksToAdd `, linksToAdd)
            } else if (causeExists) {
                /** 
                 * if the left node exists then
                 * (1) create the right node
                 * (2) update the left node by pushing the id of the right node to node wires
                 * (3) add the right node to the flow
                 * */
                // only cause node exists
                console.log(`${_module} addNewRelations [ only left node exists ]`, causeNode)
                let query_value = req.body.nn !== undefined ? req.body.nn[causeName] : causeNode.id

                // get cause node 
                if (flow !== null) {
                    for await (let node of flow.nodes) {
                        if (node.id === query_value) { causeNode = node }
                        nodeX = nodeX < node.x ? node.x : nodeX
                        nodeY = nodeY < node.y ? node.y : nodeY
                    }
                }
                for await (let node of nodesToAdd) {
                    if (node.id === query_value) { causeNode = node }
                    nodeX = nodeX < node.x ? node.x : nodeX
                    nodeY = nodeY < node.y ? node.y : nodeY
                }
                console.log(`${_module} addNewRelations [ only left node exists ] nodeX ${nodeX}  nodeY ${nodeY}`)


                if (linksToAdd.hasOwnProperty(causeNode.id)) {
                    multiple = linksToAdd[causeNode.id].length
                }
                let effectX = causeNode.x + 250
                let effectY = causeNode.y + incrementY * multiple
                console.log(`${_module} addNewRelations [ only left node exists ] incrementY ${incrementY}  multiple ${multiple}`)
                console.log(`${_module} addNewRelations [ only left node exists ] effectX ${effectX} effectY ${effectY}`)

                //  (1) create effectNode
                effectNode = {
                    id: await getNodeRedId(),
                    type: "causeeffect",
                    z: flowId,
                    name: effectName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanism: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: effectX,
                    y: effectY,
                    wires: [[]],
                }

                // (3) add effectNode to flow
                nodesToAdd.push(effectNode)
                if (linksToAdd.hasOwnProperty(causeNode.id)) {
                    let items = new Set(linksToAdd[causeNode.id])
                    if (!items.has(effectNode.id)) {
                        linksToAdd[causeNode.id].push(effectNode.id)
                    }
                } else {
                    linksToAdd[causeNode.id] = [effectNode.id]
                }

            } else if (effectExists) {

                /** 
                 * if the right node exists then
                 * 1 find effect node and store its x and y values
                 * 2 initialize left node and add to its wires the node red id
                 * 3 find the right node to update the left node x,y,and wires
                 * 4 add new left node to the flow's nodes
                 * */
                console.log(`${_module} addNewRelations [ only right node exists ] effectNode`, effectNode)
                let query_value = req.body.nn !== undefined ? req.body.nn[effectName] : effectNode.id
                console.log(`${_module} addNewRelations [ only right node exists ] query value`, query_value)

                //1 find effect node and store its x and y values
                if (flow !== null) {
                    for await (let node of flow.nodes) {
                        if (node.id === query_value) { effectNode = node }
                        nodeX = nodeX < node.x ? node.x : nodeX
                        nodeY = nodeY < node.y ? node.y : nodeY
                    }
                }

                for await (let node of nodesToAdd) {
                    if (node.id === query_value) { effectNode = node }
                    nodeX = nodeX < node.x ? node.x : nodeX
                    nodeY = nodeY < node.y ? node.y : nodeY
                }

                //2 initialize left node using causeeffect json
                causeNode = {
                    id: await getNodeRedId(),
                    type: "causeeffect",
                    z: flowId,
                    name: causeName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanism: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: "",
                    y: "",
                    wires: [[effectNode.id]],
                }

                // find immediate parents of node
                console.log(`${_module} addNewRelations [ only right node exists ] linksToAdd`, linksToAdd)
                if (linksToAdd.hasOwnProperty(effectNode.id)) {
                    multiple = linksToAdd[effectNode.id].length
                }
                let effectX = causeNode.x + 250
                let effectY = causeNode.y + incrementY * multiple
                console.log(`${_module} addNewRelations [ only left node exists ] incrementY ${incrementY}  multiple ${multiple}`)
                console.log(`${_module} addNewRelations [ only left node exists ] effectX ${effectX} effectY ${effectY}`)

                // 3 find the right node to update the left node x,y,and wires
                let effectParents = []
                if (flow !== null) {
                    for await (let node of flow.nodes) {
                        for await (let wire of node.wires[0]) {
                            console.log(`${_module} addNewRelations [ only right node exists ] effect === wire ${wire} ${effectNode.id} `, wire === effectNode.id)
                            if (wire === effectNode.id) {
                                effectParents.push(wire)
                            }
                        }
                    }
                }

                let effectWires = [];
                for await (let link of Object.keys(linksToAdd)) {
                    console.log(`${_module} addNewRelations link`, link, effectNode.id)
                    if (link === effectNode.id) {
                        effectWires = linksToAdd[link]
                    }
                    for await (let linkEffect of linksToAdd[link]) {
                        if (linkEffect === effectNode.id) {
                            effectParents.push(linkEffect)
                        }
                    }
                }

                incrementY = 75
                multiple = effectParents.length
                console.log(`${_module} addNewRelations [ only right node exists ] total parents `, effectParents.length)
                causeNode.x = effectNode.x - 250
                causeNode.y = effectNode.y + incrementY * multiple
                if (causeNode.x < 50) {
                    causeNode.x = 50
                    effectNode.x = 250
                }

                await updateDownstream(effectWires, flow, nodesToAdd, effectNode, linksToAdd)

                // (3) add left node to flow nodes
                nodesToAdd.push(causeNode)
                if (linksToAdd.hasOwnProperty(causeNode.id)) {
                    let items = new Set(linksToAdd[causeNode.id])
                    if (!items.has(effectNode.id)) {
                        linksToAdd[causeNode.id].push(effectNode.id)
                    }
                } else {
                    linksToAdd[causeNode.id] = [effectNode.id]
                }

            } else if (!causeExists && !effectExists) {
                /** 
                  * if neither left or right node exists
                  * (1) initialize left node
                  * (2) initialize right node
                  * (3) update nodes' x,y, and wire fields with actual values
                  * (4) add nodes to the flow
                  * */
                console.log(`${_module}  ${_func_name}  Neither node exists`)
                // (1) initialize causeNode
                causeNode = {
                    id: await getNodeRedId(),
                    type: "causeeffect",
                    z: flowId,
                    name: causeName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanism: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: nodeX,
                    y: nodeY,
                    wires: [[]],
                }
                // (2) initialize effectNode
                effectNode = {
                    id: await getNodeRedId(),
                    type: "causeeffect",
                    z: flowId,
                    name: effectName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanism: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: nodeX += 250,
                    y: nodeY,
                    wires: [[]],
                }
                causeNode.wires[0].push(effectNode.id)
                //  (4) add nodes to the flow
                nodesToAdd.push(causeNode)
                nodesToAdd.push(effectNode)
                if (linksToAdd.hasOwnProperty(causeNode.id)) {
                    let items = new Set(linksToAdd[causeNode.id])
                    if (!items.has(effectNode.id)) {
                        linksToAdd[causeNode.id].push(effectNode.id)
                    }
                } else {
                    linksToAdd[causeNode.id] = [effectNode.id]
                }
            }

            // iterate through recent results to see if relation is added
            await gpt_recent.forEach(cr_set => {
                cr_set.forEach(cr => {
                    if (cr.label === relation[0][0]) {
                        cr.sublabel = "added"
                    }
                })
            })
        }

        // await ctx.set("gpt_recent_results", gpt_recent)
        workspace["gpt_recent_results"] = gpt_recent
        let updatedFlow = await updateWorkspaceContext(req.body.activeWorkspace, workspace)
        delete seenNodes
        res.status(200).send({
            gpt_results: "ok",
            nodesToAdd: nodesToAdd,
            linksToAdd: linksToAdd,
            updatedFlow: updatedFlow
        })
    } catch (exception) {
        console.log(`${_module} addNewRelations exception`, exception)
        res.status(500).send({ error: exception })
    }
}

async function updateGptInfo(activeWorkspace, key, value) {
    let _func_name = "[updateGptInfo]"
    console.log(`${_module} ${_func_name}  ${key} ==================================`)
    /* [ disconnecting from the old attribute value ]
        match $org isa organisation, has name "Medicely", has registration-number $rn; 
        delete $org has $rn;
        insert $org has registration-number "81726354";
    */

    // temporarily convert key 
    key = key === "llm_api_key" ? "gpt_api_key" : key
    try {
        let opts = {
            "db": "causeway-repo",
            "query": `match $gpt_info isa gpt_info, has nrid \"${activeWorkspace}\", has ${key} $${key}; get $${key};`,
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ",
            "caller": "update-gpt-info"
        }
        value = value.replaceAll('\"', '\\"')
        let _result = await typedbApi.executeQuery(opts)
        opts["transaction_type"] = "WRITE"
        // insert - update  attribute
        if (_result.length === 0) {
            console.log(`${_module} ${_func_name} inserting attribute`)
            opts["query_type"] = "insert"
            opts["query"] = `match $gpt_info isa gpt_info, has nrid \"${activeWorkspace}\";\ninsert $gpt_info has ${key} \"${value}\";`
        } else {
            console.log(`${_module} ${_func_name} updating attribute ${key}`)
            opts["query_type"] = "update"
            opts["query"] = `match $gpt_info isa gpt_info, has nrid \"${activeWorkspace}\", has ${key} $${key};\n delete $gpt_info has $${key};\ninsert $gpt_info has ${key} \"${value}\";`
        }
        await typedbApi.executeQuery(opts)
        console.log(`${_module} ${_func_name} update_gpt_info for ${key} successful ${String.fromCharCode(0x2611)} `)

    } catch (exception) {
        console.log(`${_module} ${_func_name} Exception ${String.fromCharCode(0x274C)} ${exception}`)
    }

}


